def count_occurrences(text, sub):
    """
    Return the number of non-overlapping, case-insensitive occurrences of sub in text.
    """
    return text.lower().count(sub.lower())
    pass

def is_palindrome(s):
    """
    Recursively check if s is a palindrome (no loops or string reversal).
    """
    if len(s) <= 1:
        return True

    if s[0] != s[-1]:
        return False

    return is_palindrome(s[1:-1])

def flatten(nested):
    """
    Recursively flatten an arbitrarily nested list into a single flat list of integers.
    """
    result = []

    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)

    return result

def count_paths(rows, cols):
    """
    Recursively count the unique top-left to bottom-right paths in a rows x cols grid (right/down moves only).
    """
    if rows == 1 or cols == 1:
        return 1

    return count_paths(rows - 1, cols) + count_paths(rows, cols - 1)

def count_paths_memo(rows, cols, memo=None):
    """
    Same as count_paths, with memoization to avoid recomputation.
    """
    if memo is None:
        memo = {}

    if rows == 1 or cols == 1:
        return 1

    if (rows, cols) in memo:
        return memo[(rows, cols)]

    memo[(rows, cols)] = (
        count_paths_memo(rows - 1, cols, memo)
        + count_paths_memo(rows, cols - 1, memo)
    )

    return memo[(rows, cols)]

class Doctor:
    def __init__(self, doctor_id, name, specialty):
        self.doctor_id = doctor_id
        self.name = name
        self.specialty = specialty


class HospitalSystem:
    def __init__(self):
        self.doctors = {}
        self.appointments = []

    def add_doctor(self, doctor_id, name, specialty):
        if doctor_id in self.doctors:
            raise ValueError("Doctor ID already exists")

        self.doctors[doctor_id] = Doctor(doctor_id, name, specialty)

    def book_appointment(self, patient_name, doctor_id, date):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")

        for appointment in self.appointments:
            if (
                appointment["doctor_id"] == doctor_id
                and appointment["date"] == date
            ):
                raise ValueError("Doctor already has an appointment on this date")

        self.appointments.append({
            "patient_name": patient_name,
            "doctor_id": doctor_id,
            "date": date
        })

    def cancel_appointment(self, patient_name, doctor_id, date):
        for appointment in self.appointments:
            if (
                appointment["patient_name"] == patient_name
                and appointment["doctor_id"] == doctor_id
                and appointment["date"] == date
            ):
                self.appointments.remove(appointment)
                return

        raise ValueError("Appointment not found")

    def get_appointments(self, doctor_id):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")

        result = []

        for appointment in self.appointments:
            if appointment["doctor_id"] == doctor_id:
                result.append(
                    f'{appointment["date"]}: {appointment["patient_name"]}'
                )

        return sorted(result)

    def get_patient_doctors(self, patient_name):
        doctor_names = set()

        for appointment in self.appointments:
            if appointment["patient_name"] == patient_name:
                doctor = self.doctors[appointment["doctor_id"]]
                doctor_names.add(doctor.name)

        return sorted(doctor_names)

class StudentManager:
    def __init__(self):
        self.students = {}

    def enroll(self, student_name, course_name):
        if student_name not in self.students:
            self.students[student_name] = set()

        if course_name in self.students[student_name]:
            raise ValueError("Student already enrolled")

        self.students[student_name].add(course_name)

    def drop(self, student_name, course_name):
        if (
            student_name not in self.students
            or course_name not in self.students[student_name]
        ):
            raise ValueError("Student not enrolled")

        self.students[student_name].remove(course_name)

        if not self.students[student_name]:
            del self.students[student_name]

    def get_courses(self, student_name):
        if student_name not in self.students:
            return []

        return sorted(self.students[student_name])

    def get_students(self, course_name):
        result = []

        for student_name, courses in self.students.items():
            if course_name in courses:
                result.append(student_name)

        return sorted(result)

    def top_student(self):
        if not self.students:
            return None

        max_courses = max(
            len(courses) for courses in self.students.values()
        )

        top_students = [
            student_name
            for student_name, courses in self.students.items()
            if len(courses) == max_courses
        ]

        return sorted(top_students)[0]

class MenuItem:
    def __init__(self, item_id, name, price, category):
        self.item_id = item_id
        self.name = name
        self.price = price
        self.category = category


class Restaurant:
    def __init__(self):
        self.menu = {}
        self.orders = {}

    def add_menu_item(self, item_id, name, price, category):
        if item_id in self.menu:
            raise ValueError("Item ID already exists")

        if price <= 0:
            raise ValueError("Invalid price")

        self.menu[item_id] = MenuItem(
            item_id, name, price, category
        )

    def place_order(self, table_number, item_id, quantity=1):
        if item_id not in self.menu:
            raise ValueError("Item not found")

        if quantity <= 0:
            raise ValueError("Invalid quantity")

        if table_number not in self.orders:
            self.orders[table_number] = {}

        if item_id not in self.orders[table_number]:
            self.orders[table_number][item_id] = 0

        self.orders[table_number][item_id] += quantity

    def remove_from_order(self, table_number, item_id, quantity=1):
        if quantity <= 0:
            raise ValueError("Invalid quantity")

        if table_number not in self.orders:
            raise ValueError("Order not found")

        if item_id not in self.orders[table_number]:
            raise ValueError("Item not found in order")

        if quantity > self.orders[table_number][item_id]:
            raise ValueError("Quantity exceeds order")

        self.orders[table_number][item_id] -= quantity

        if self.orders[table_number][item_id] == 0:
            del self.orders[table_number][item_id]

    def get_bill(self, table_number):
        if table_number not in self.orders:
            return "No orders for table"

        if not self.orders[table_number]:
            return "No orders for table"

        lines = []
        total = 0

        ordered_items = []

        for item_id, quantity in self.orders[table_number].items():
            item = self.menu[item_id]
            ordered_items.append((item.name, item, quantity))

        ordered_items.sort()

        for name, item, quantity in ordered_items:
            subtotal = item.price * quantity
            total += subtotal

            lines.append(
                f"{name} x{quantity} = PHP {round(float(subtotal), 2)}"
            )

        lines.append(
            f"Total: PHP {round(float(total), 2)}"
        )

        return "\n".join(lines)

    def get_menu_by_category(self, category):
        result = []

        for item in self.menu.values():
            if item.category == category:
                result.append(item.name)

        return sorted(result)

class Product:
    def __init__(self, name, price, stock):
        self.name = name
        self.price = price
        self.stock = stock


class Store:
    def __init__(self):
        self.products = {}

    def add_product(self, name, price, stock):
        self.products[name] = Product(name, price, stock)

    def buy(self, name, quantity):
        if name not in self.products:
            raise ValueError("Product not found")

        if quantity <= 0:
            raise ValueError("Invalid quantity")

        product = self.products[name]

        if product.stock < quantity:
            raise ValueError("Insufficient stock")

        product.stock -= quantity

    def restock(self, name, quantity):
        if name not in self.products:
            raise ValueError("Product not found")

        if quantity <= 0:
            raise ValueError("Invalid quantity")

        self.products[name].stock += quantity

    def total_value(self):
        return round(
            sum(
                product.price * product.stock
                for product in self.products.values()
            ),
            2
        )

    def available_products(self):
        return sorted(
            product.name
            for product in self.products.values()
            if product.stock > 0
        )

class Book:
    def __init__(self, title, author, available=True):
        self.title = title
        self.author = author
        self.available = available


class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author):
        book = Book(title, author)
        self.books.append(book)

    def borrow_book(self, title):
        for book in self.books:
            if book.title == title:
                if not book.available:
                    raise ValueError("Book is already borrowed")

                book.available = False
                return

        raise ValueError("Book not found")

    def return_book(self, title):
        for book in self.books:
            if book.title == title:
                if book.available:
                    raise ValueError("Book is not borrowed")

                book.available = True
                return

        raise ValueError("Book not found")

    def available_books(self):
        titles = []

        for book in self.books:
            if book.available:
                titles.append(book.title)

        return sorted(titles)

    def search_by_author(self, author):
        titles = []

        for book in self.books:
            if book.author == author:
                titles.append(book.title)

        return sorted(titles)

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def find_middle(head):

    if head is None:
        return None

    slow = head
    fast = head

    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next

    return slow.val

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def delete_node(head, val):

    if head is None:
        return None

    if head.val == val:
        return head.next

    current = head
    while current.next is not None:
        if current.next.val == val:
            current.next = current.next.next
            break
        current = current.next

    return head

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def merge_sorted(l1, l2):

    dummy = ListNode(0)
    current = dummy

    while l1 is not None and l2 is not None:
        if l1.val <= l2.val:
            current.next = l1  
            l1 = l1.next       
        else:
            current.next = l2  
            l2 = l2.next       

        current = current.next 

    if l1 is not None:
        current.next = l1
    elif l2 is not None:
        current.next = l2

    return dummy.next

