def transpose(matrix):
    """
    Return the transpose of matrix (rows become columns). Do not modify the original.
    """
    if not matrix:
        return []

    return [list(column) for column in zip(*matrix)]


def multiply(A, B):
    """
    Return the matrix product of A and B. Raise ValueError if dimensions are incompatible.
    """
    if not A or not B:
        return []

    if len(A[0]) != len(B):
        raise ValueError("Incompatible matrix dimensions")

    return [
        [sum(A[i][k] * B[k][j] for k in range(len(B)))
         for j in range(len(B[0]))]
        for i in range(len(A))
    ]

def main_diagonal(matrix):
    """
    Return the elements on the main diagonal (top-left to bottom-right).
    """
    return [matrix[i][i] for i in range(len(matrix))]


def anti_diagonal(matrix):
    """
    Return the elements on the anti-diagonal (top-right to bottom-left).
    """
    n = len(matrix)
    return [matrix[i][n - 1 - i] for i in range(n)]


def is_symmetric(matrix):
    """
    Return True if matrix equals its transpose.
    """
    n = len(matrix)

    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False

    return True


def trace(matrix):
    """
    Return the sum of the main diagonal elements.
    """
    return sum(matrix[i][i] for i in range(len(matrix)))

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def find_middle(head):
    """
    Return the value of the middle node using slow/fast pointers (second middle if even length).
    """
    if head is None:
        return None

    slow = head
    fast = head

    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next

    return slow.val

def is_palindrome(s):
    """
    Recursively check if s is a palindrome (no loops or string reversal).
    """
    if len(s) <= 1:
        return True

    if s[0] != s[-1]:
        return False

    # Small mistake: skips two characters from each side
    return is_palindrome(s[2:-2])

class UndoSystem:

    def __init__(self):
        self.doc = ""
        self.history = []

    def type(self, text):
        self.history.append(self.doc)
        self.doc += text

    def undo(self):
        if self.history:
            self.doc = self.history.pop()

    def get_document(self):
        return self.doc

class Queue:

    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if self.is_empty():
            raise IndexError("Queue is empty")
        return self.items.pop(0)

    def peek(self):
        if self.is_empty():
            raise IndexError("Queue is empty")
        return self.items[0]

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

def selection_sort(arr):
    """
    Sort arr ascending using selection sort. Return the sorted list.
    """
    n = len(arr)
    for i in range(n - 1):
        min_index = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j
        arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr

def bubble_sort(arr):
    """
    Sort arr ascending using bubble sort with early termination. Return the sorted list.
    """
    n = len(arr)
    for i in range(n - 1):
        swapped = False
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

def check_loan(age, income, credit_score, existing_loans):
    """
    Evaluate a loan application against a sequence of eligibility rules and return the result string.
    """
    if age < 18:
        return "Rejected: Underage"
    if income < 15000:
        return "Rejected: Insufficient income"
    if credit_score < 600:
        return "Rejected: Poor credit score"
    if existing_loans >= 3:
        return "Rejected: Too many existing loans"
    if credit_score >= 750 and income >= 50000:
        return "Approved: Premium"
    if credit_score >= 700:
        return "Approved: Standard"
    return "Approved: Basic"

def transform_string(text, operations):
    """
    Apply each operation in operations to text in order, and return the result. Unrecognized ops are skipped.
    """
    for op in operations:
        if op == "upper":
            text = text.upper()
        elif op == "lower":
            text = text.lower()
        elif op == "title":
            text = text.title()
        elif op == "reverse":
            text = text[::-1]
        elif op == "strip":
            text = text.strip()
        elif op == "remove_spaces":
            text = text.replace(" ", "")
        elif op == "replace_vowels":
            text = "".join("*" if ch in "aeiouAEIOU" else ch for ch in text)
    return text

def collatz(n):
    """
    Return the Collatz sequence starting at n and ending at 1, inclusive of both endpoints.
    """
    sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        sequence.append(n)
    return sequence

class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("error")
        self.balance -= amount

    def get_balance(self):
        return self.balance

    def __str__(self):
        return f"{self.owner}: {self.balance}"

class SavingsAccount(Account):
    def __init__(self, owner, balance, interest_rate):
        super().__init__(owner, balance)
        self.interest_rate = interest_rate

    def apply_interest(self):
        self.balance = round(
            self.balance * (1+self.interest_rate/100), 2
        )

    def withdraw(self, amount):
        if self.balance - amount < 500:
            raise ValueError("error")
        self.balance -= amount

class CreditAccount(Account):
    def __init__(self, owner, credit_limit):
        super().__init__(owner, 0)
        self.credit_limit = credit_limit

    def withdraw(self, amount):
        if self.balance - amount < -self.credit_limit:
            raise ValueError("error")
        self.balance -= amount

    def available_credit(self):
        return self.credit_limit+self.balance

