    def describe(self):
        area_val = round(self.area(), 2)
        if area_val == int(area_val):
            area_str = f"{area_val:.1f}"
        else:
            area_str = f"{area_val:.2f}"
        return f"I am a {self.__class__.__name__} with area {area_str}"


